"""Independent transcription of the replay rules, used only by the dev tests."""
import json, os, struct, sys
sys.path[:0] = ['/workspace/project', '/opt/emicro-deps']
from ebpf.create_dfa import create

DENY = 4294967295
U32 = 4294967295
REJ = {'error': 'rejected'}
OK = {'ok': True}


class Model:
    def __init__(self, services, limits):
        self.services = list(services)
        self.limits = dict(limits)
        ordered = sorted(services, key=lambda s: s['label'])
        self.column = {s['name']: i for i, s in enumerate(ordered)}
        self.label = {s['name']: s['label'] for s in services}
        self.images = {}          # epoch -> dict(accept, rows, cells, refs)
        self.active = None
        self.stage_mark = 0
        self.units = {}           # (ns,pid) -> dict
        self.unit_gen = {}        # (ns,pid) -> last spawn/clone generation
        self.conns = {}           # id -> dict
        self.conn_gen = {}        # id -> last open generation
        self.files = {}           # id -> dict
        self.file_gen = {}        # id -> last store generation
        self.contexts = 0
        self.packets = 0

    # ---------------------------------------------------------------- helpers
    def ref(self, epoch, delta):
        self.images[epoch]['refs'] += delta

    def rows(self, epoch):
        return self.images[epoch]['rows']

    def full(self, kind, used, extra=1):
        cap = self.limits[kind]
        return used + extra > cap

    # ------------------------------------------------------------------ events
    def do(self, e):
        op = e['op']
        return getattr(self, '_' + op)(e)

    def _stage(self, e):
        epoch = e['epoch']
        if epoch <= self.stage_mark:
            return REJ
        if self.full('images', len(self.images)):
            return REJ
        try:
            image = create(e['policy'], self.services)
        except Exception:
            return REJ
        if len(image['rows']) > 8192:
            return REJ
        if self.full('cells', sum(v['cells'] for v in self.images.values()), image['cells']):
            return REJ
        self.images[epoch] = {'accept': list(image['accept']), 'rows': [list(r) for r in image['rows']],
                              'cells': image['cells'], 'refs': 0}
        self.stage_mark = epoch
        return {'ok': True, 'epoch': epoch,
                'image': {'accept': list(image['accept']), 'rows': [list(r) for r in image['rows']]}}

    def _commit(self, e):
        if e['epoch'] not in self.images:
            return REJ
        self.active = e['epoch']
        return OK

    def _retire(self, e):
        epoch = e['epoch']
        img = self.images.get(epoch)
        if img is None or epoch == self.active or img['refs'] != 0:
            return REJ
        del self.images[epoch]
        return OK

    def _identity_ok(self, identity):
        key = (identity[0], identity[1])
        if key in self.units:
            return False
        if identity[2] <= self.unit_gen.get(key, 0):
            return False
        return True

    def _spawn(self, e):
        service = e['service']
        if service not in self.column:
            return REJ
        identity = e['unit']
        if not self._identity_ok(identity):
            return REJ
        if self.full('units', len(self.units)):
            return REJ
        key = (identity[0], identity[1])
        self.units[key] = {'service': service, 'gen': identity[2], 'mark': 0, 'ctx': {}}
        self.unit_gen[key] = identity[2]
        return OK

    def _clone(self, e):
        parent, child = e['parent'], e['child']
        pu = self.units.get((parent[0], parent[1]))
        if pu is None or pu['gen'] != parent[2]:
            return REJ
        if not self._identity_ok(child):
            return REJ
        if self.full('units', len(self.units)):
            return REJ
        needed = len(pu['ctx'])
        if self.full('contexts', self.contexts, needed):
            return REJ
        key = (child[0], child[1])
        copied = {}
        for rid, (epoch, state) in pu['ctx'].items():
            copied[rid] = (epoch, state)
            self.ref(epoch, 1)
        self.units[key] = {'service': pu['service'], 'gen': child[2], 'mark': pu['mark'], 'ctx': copied}
        self.unit_gen[key] = child[2]
        self.contexts += needed
        return OK

    def _exit(self, e):
        identity = e['unit']
        unit = self.units.get((identity[0], identity[1]))
        if unit is None or unit['gen'] != identity[2]:
            return REJ
        del self.units[unit_key := (identity[0], identity[1])]
        for epoch, _state in unit['ctx'].values():
            self.ref(epoch, -1)
        self.contexts -= len(unit['ctx'])
        return OK

    def _unit_ctx(self, identity, rid):
        unit = self.units.get((identity[0], identity[1]))
        if unit is None or unit['gen'] != identity[2]:
            return None, REJ
        context = unit['ctx'].get(rid)
        if context is None:
            return None, REJ
        return (unit, context), OK

    def _begin(self, e):
        if self.active is None:
            return REJ
        identity, rid = e['unit'], e['rid']
        unit = self.units.get((identity[0], identity[1]))
        if unit is None or unit['gen'] != identity[2]:
            return REJ
        if rid <= unit['mark']:
            return REJ
        if self.full('contexts', self.contexts):
            return REJ
        image = self.images[self.active]
        state = image['rows'][0][self.column[unit['service']]]
        unit['ctx'][rid] = (self.active, state)
        unit['mark'] = rid
        self.ref(self.active, 1)
        self.contexts += 1
        return {'ok': True, 'epoch': self.active, 'state': state}

    def _finish(self, e):
        identity, rid = e['unit'], e['rid']
        packed, status = self._unit_ctx(identity, rid)
        if status is not OK:
            return status
        unit, context = packed
        del unit['ctx'][rid]
        image = self.images[context[0]]
        self.ref(context[0], -1)
        self.contexts -= 1
        allow = False if context[1] == DENY else bool(image['accept'][context[1]])
        return {'ok': True, 'allow': allow}

    def _open(self, e):
        identifier, generation = e['connection']
        if identifier in self.conns:
            return REJ
        if generation <= self.conn_gen.get(identifier, 0):
            return REJ
        if self.full('connections', len(self.conns)):
            return REJ
        self.conns[identifier] = {'gen': generation, 'mark': 0, 'packets': {}}
        self.conn_gen[identifier] = generation
        return OK

    def _send(self, e):
        destination = e['destination']
        if destination not in self.label:
            return REJ
        packed, status = self._unit_ctx(e['unit'], e['rid'])
        if status is not OK:
            return status
        unit, context = packed
        identifier, generation = e['connection']
        conn = self.conns.get(identifier)
        if conn is None or conn['gen'] != generation:
            return REJ
        stream = e['stream']
        if stream <= conn['mark']:
            return REJ
        if self.full('packets', self.packets):
            return REJ
        wire = struct.pack('>4sIIIII', b'EMC4', context[0], context[1],
                           self.label[destination], stream, generation).hex()
        conn['packets'][stream] = {'epoch': context[0], 'state': context[1],
                                   'destination': destination, 'wire': wire, 'receipt': None}
        conn['mark'] = stream
        self.ref(context[0], 1)
        self.packets += 1
        return {'ok': True, 'wire': wire}

    def _recv(self, e):
        identifier, generation = e['connection']
        conn = self.conns.get(identifier)
        if conn is None or conn['gen'] != generation:
            return REJ
        packet = conn['packets'].get(e['stream'])
        if packet is None:
            return REJ
        identity, rid = e['unit'], e['rid']
        unit = self.units.get((identity[0], identity[1]))
        if unit is None or unit['gen'] != identity[2]:
            return REJ
        if unit['service'] != packet['destination']:
            return REJ
        if e['wire'] is not None:
            wire = e['wire']
            if len(wire) != 48 or wire.lower() != packet['wire']:
                return REJ
        receipt = packet['receipt']
        if receipt is not None:
            held, marked, epoch, state = receipt
            if held != tuple(identity) or marked != rid:
                return REJ
            if unit is None or unit['gen'] != identity[2] or rid not in unit['ctx']:
                return REJ
            if unit['ctx'][rid] != (epoch, state):
                return REJ
            return {'ok': True, 'epoch': epoch, 'state': state}
        if rid <= unit['mark']:
            return REJ
        if self.full('contexts', self.contexts):
            return REJ
        epoch = packet['epoch']
        state = DENY if packet['state'] == DENY else self.rows(epoch)[packet['state']][self.column[unit['service']]]
        unit['ctx'][rid] = (epoch, state)
        unit['mark'] = rid
        self.ref(epoch, 1)
        self.contexts += 1
        packet['receipt'] = (tuple(identity), rid, epoch, state)
        return {'ok': True, 'epoch': epoch, 'state': state}

    def _close(self, e):
        identifier, generation = e['connection']
        conn = self.conns.get(identifier)
        if conn is None or conn['gen'] != generation:
            return REJ
        del self.conns[identifier]
        for packet in conn['packets'].values():
            self.ref(packet['epoch'], -1)
        self.packets -= len(conn['packets'])
        return OK

    def _store(self, e):
        packed, status = self._unit_ctx(e['unit'], e['rid'])
        if status is not OK:
            return status
        _unit, context = packed
        identifier, generation = e['file']
        current = self.files.get(identifier)
        if current is None:
            if generation <= self.file_gen.get(identifier, 0):
                return REJ
            if self.full('files', len(self.files)):
                return REJ
        elif current['gen'] != generation:
            return REJ
        self.files[identifier] = {'gen': generation, 'epoch': context[0], 'state': context[1]}
        self.file_gen[identifier] = max(self.file_gen.get(identifier, 0), generation)
        self.ref(context[0], 1)
        if current is not None:
            self.ref(current['epoch'], -1)
        return OK

    def _load(self, e):
        identifier, generation = e['file']
        current = self.files.get(identifier)
        if current is None or current['gen'] != generation:
            return REJ
        identity, rid = e['unit'], e['rid']
        unit = self.units.get((identity[0], identity[1]))
        if unit is None or unit['gen'] != identity[2]:
            return REJ
        if rid <= unit['mark']:
            return REJ
        if self.full('contexts', self.contexts):
            return REJ
        epoch = current['epoch']
        state = DENY if current['state'] == DENY else self.rows(epoch)[current['state']][self.column[unit['service']]]
        unit['ctx'][rid] = (epoch, state)
        unit['mark'] = rid
        self.ref(epoch, 1)
        self.contexts += 1
        return {'ok': True, 'epoch': epoch, 'state': state}

    def _unlink(self, e):
        identifier, generation = e['file']
        current = self.files.get(identifier)
        if current is None or current['gen'] != generation:
            return REJ
        del self.files[identifier]
        self.ref(current['epoch'], -1)
        return OK

    def _inspect(self, e):
        images = []
        for epoch in sorted(self.images):
            image = self.images[epoch]
            images.append([epoch, len(image['rows']), image['cells'], image['refs']])
        return {'ok': True, 'active': self.active, 'images': images,
                'units': len(self.units), 'contexts': self.contexts,
                'connections': len(self.conns), 'packets': self.packets,
                'files': len(self.files)}
